parameters.text:
=Generate a high-converting YouTube Short script about {{ $json.topic }}.
HARD LIMIT: hook + script_body together must be at most {{ $json.max_words }} words (about 30 seconds spoken). No emojis, no hashtags in spoken text.
The pinned_comment_call_to_action must end with this exact link: {{ $json.affiliate_link }}

parameters.jsCode:
// Robust parser: strips <think> blocks, markdown fences, and any text around the JSON object
const raw = String($input.first().json.output ?? $input.first().json.text ?? '');
let s = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```json|```/gi, '').trim();
const start = s.indexOf('{');
const end = s.lastIndexOf('}');
if (start === -1 || end === -1) throw new Error('No JSON object found in model output: ' + raw.slice(0, 300));
const data = JSON.parse(s.slice(start, end + 1));

// Spoken voiceover = hook + body; remove characters TTS would read awkwardly
const voiceover_text = [data.hook, data.script_body].filter(Boolean).join(' ')
  .replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}\u{20E3}]/gu, '').replace(/[*_#`]/g, '').replace(/\s+/g, ' ').trim();

// Base64 so quotes/apostrophes can't break the Windows command line
const b64 = (str) => (typeof Buffer !== 'undefined')
  ? Buffer.from(str, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(str)));

const slug = String(data.video_title || 'short').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
const run_id = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-') + '_' + slug;

return [{ json: {
  ...data,
  run_id,
  voiceover_text,
  voiceover_b64: b64(voiceover_text),
  data_b64: b64(JSON.stringify({ ...data, voiceover_text }, null, 2)),
} }];

